import { PEOPLE } from './data.js';

const person=id=>PEOPLE.find(p=>p.id===id);
export const romanceKey=(id,index)=>`romance:${id}:${index}`;
export const preludeKey=(a,b,index)=>`npc-prelude:${[a,b].sort().join(':')}:${index}`;
export const romanceProgress=(run,id)=>[0,1].filter(i=>run.storyFlags[romanceKey(id,i)]).length;
export const preludeProgress=(run,a,b)=>[0,1].filter(i=>run.storyFlags[preludeKey(a,b,i)]).length;

const PERSONAL={
  raina:[['没有雨声的下一站','雨音终于带你去了一个没有雨声的世界。她几次想跳回熟悉的座位，又问你愿不愿意和她把这条陌生的小路走完。“原来我想约的人，不只是收藏夹里的风景。”她把下次邀请留给了你。'],['把等待讲成一句话','上次的邀请之后，雨音有一晚没有回复。再见时，她说自己需要安静，也想知道你是否还愿意靠近。你们没有把沉默当成拒绝，而是谈起怎样让等待不变成猜测。她轻声说：“我已经开始期待见到你了，但想慢一点。”']],
  mika:[['相机收起来以后','小满把相机留在背包里，想试一次没有截图的散步。你们记住了路灯下面聊过的小事。临下线前她问，下次能不能再留一段只属于相处、无需发布的时间。'],['没能兑现的那张日历','小满想约的晚上，你们的安排没有重叠。她先有些失落，后来承认自己怕喜欢变成只有她在记着。你们聊清改期、回应与各自的生活，她说这份邀请已经和普通朋友有一点不同。']],
  rei:[['留给你的一小段日出','零点把工程停在可以保存的位置，带你看他那个时区的日出。你们聊了作品之外的生活。分开时，他第一次留下的不是修改任务，而是“有空时，想再听你讲讲今天”。'],['不靠熬夜重叠的时间','一份邀约让你们发现，想见面并不能让时差消失。零点说他不希望你为他熬夜，也坦白自己会期待那短暂的交集。你们认真讨论能做到的陪伴，喜欢开始有了可以承担的形状。']],
  lin:[['音乐关掉后的邀请','演出结束，凛没有重新打开歌单。她邀你去一张小地图，只讲今晚有点疲惫和一件普通的开心。你听见舞台之外的她。散场时，她问下一次能不能也这样，不准备节目地见面。'],['喜欢不必一直热闹','凛临时取消了一次相约，担心你觉得她变冷淡了。再见时，她问：“如果我没力气带气氛，你还想来吗？”你们说清取消并不等于不在意，也让她可以认真表达想靠近与想独处的愿望。']],
  yuki:[['没有修改清单的晚饭','弥生带着还没修完接缝的模型赴约。你们没有打开工程，只聊了最初喜欢上创作的理由。她发现可以被邀请的不是一个帮忙改模的人，而是她自己。下线前，她留了一只只发给你的纸鸟。'],['把关心从工程里拿出来','弥生一直把新做的模型发给你，却不敢直接说想见面。一次错过邀约之后，你们谈起作品、陪伴和“没有帮上忙也值得被喜欢”。她终于说，这次想给你的不只是一个工程文件。']],
  ash:[['轮到向导迷路','阿澈邀请你走一条自己也没看过的路线。你们轮流带路，谁都不必一直负责照顾另一个人。'],['朋友的位置也很重要','阿澈认真说自己珍惜这段朋友关系，希望把期待讲明白。亲近可以继续，但他不想许下恋爱承诺。']],
};

const PAIRS={
  'lin:mika':{narrator:'yuki',chapters:[['没有发布的下一次邀请','拍照那晚之后，小满又邀请凛见了一次面。这回凛没有演出，小满也没带相机。她们轮流选了喜欢的歌，发现可以认识镜头与舞台之外的彼此。临散场，两个人约好还有下一次。'],['失约之后先听见对方','下一次邀请撞上了演出准备。小满有些失落，凛却以为只有表现得热闹才值得见面。她们把失约与担心讲开，重新安排了不需要拍照或表演的时间。喜欢没有立即得到名字，却开始被认真回应。']]},
  'rei:yuki':{narrator:'ash',chapters:[['工程关闭之后的二十分钟','合作过灯光之后，零点与弥生又约了一次见面。这次保存完工程，两个人没有继续报错，而是交换窗外的天气。弥生留了一只纸鸟，零点记下她想看的日出。他们开始期待没有任务的邀请。'],['不把陪伴算成工作时长','一次相约被临时修改和时差打乱，弥生以为自己被放到最后，零点担心只能靠熬夜补偿。他们重新讨论可兑现的时间，也说清想见面的对象是对方本人。彼此的在意，第一次没有藏在工程备注里。']]},
  'mika:raina':{narrator:'lin',chapters:[['云朵后面多了一句话','留言板建立后，雨音开始给小满发完整的晚安。小满回了一张不需要公开的风景照，两个人另约了一个安静的晚上。她们发现，短短的消息也可以是专门留给某个人的回应。'],['空白的晚上不是忘记','小满想再见面，雨音却需要给自己留一晚空白。她们一度都不敢问：一个怕被忘记，一个怕必须秒回。把担心讲开之后，小满记住了下一次的时间，雨音也主动表达了想见到她的愿望。']]},
  'lin:rei':{narrator:'mika',chapters:[['谢幕后又约了一首歌','舞台灯关掉以后，零点与凛又见了一次。这次没有设备需要维修，也没有节目需要主持。凛选了一首只想安静听的歌，零点说了远处那个早晨的生活。他们开始记住作品之外的彼此。'],['几份邀约之间的真实期待','新邀请和各自已有的安排撞在一起。零点与凛没有把谁藏起来，也没有急着让某个人退让。他们先说清自己想靠近的愿望，哪些时间能够兑现，哪些约定必须再和已有搭档讨论。']]},
  'lin:yuki':{narrator:'raina',chapters:[['不带修改清单的下一次','发光耳机做完之后，凛又邀弥生见面。弥生带来了材质笔记，凛却先问她最近有没有好好吃饭。工程被收起来，两个人终于有了一段不需要创造什么也值得留下的时间。'],['被邀请的不是一个工具','下一次相约时，弥生下意识准备继续改模，凛却觉得自己的关心没有被听见。她们停下来，说清不是作品做得够好才可以被喜欢。彼此表达想见面的愿望，也没有省略已有的亲密约定。']]},
};

export function courtshipScene(run,p) {
  const a=person(p.npc),b=person(p.other),index=p.index || 0;
  if(p.id==='courtship') {
    const [title,text]=PERSONAL[a.id][index];
    return {npc:a.id,title,subtitle:`心意前的相处 · ${index+1} / 2 · ${a.name}`,
      text,choices:[{label:index?'坦诚说出期待，也认真听 TA 的愿望':'珍惜这次邀请，给下一次相处留位置',text:index?'你们没有靠一句承诺结束讨论，各自把能做到与不能做到的事说清楚。':'这次相处被你们认真记住，下一次见面也不用急着定义关系。',effects:{},rel:{trust:4,affection:3},outcome:'courtship-read'},
      {label:index?'暂时不表达喜欢，先把朋友关系过好':'慢慢了解，不急着给关系起名字',text:'你们保留了继续相处的空间，也尊重关系可以停留在朋友的位置。',effects:{},rel:{trust:3},outcome:'courtship-read'}]};
  }
  if(p.id!=='npc-prelude')return null;
  const data=PAIRS[[a.id,b.id].sort().join(':')],[title,text]=data.chapters[index];
  const reporter=p.narrator?person(p.narrator):null;
  return {npc:a.id,other:b.id,title,subtitle:`砂糖前的故事 · ${index+1} / 2 · ${reporter?reporter.name+'转述':'你亲自经历'}`,
    text:reporter?`${reporter.name}聊起一件得到当事人同意分享的事。TA 没有把谁的喜欢当作已经确定的消息，只把两个人怎样相处讲给你听。\n\n${text}\n\n你没有在那次见面现场；这是他们愿意让朋友知道的一段近况。`:`你和${a.name}、${b.name}一起度过了这一晚。\n\n${text}\n\n你见到了他们怎样听彼此说话，也知道相处与确认砂糖之间，还可以留出更多时间。`,
    choices:[{label:reporter?'认真听完，下次见面时尊重他们自己的节奏':'听两人把愿望讲完，不急着替他们定义关系',text:'你记住了这段靠近的过程。两个人愿意继续了解，但还没有因此确认砂糖。',effects:{},rel:reporter?{}:{trust:2},otherRel:reporter?{}:{trust:2},castRel:reporter?{[reporter.id]:{trust:2}}:{},npcLinkDelta:4,outcome:'npc-prelude-read'},
      {label:'提醒大家不要把心意猜测当作关系结论',text:'他们愿意继续认真相处，也保留可以不成为砂糖的选择。',effects:{},rel:{},otherRel:{},npcLinkDelta:3,outcome:'npc-prelude-read'},
      {label:'把这段经历当作已经在一起，替他们传开',text:'两个人澄清还没有确认关系。被旁人抢先定义的压力，让他们更需要时间重新建立信任。',effects:{},rel:{trust:-3},otherRel:{trust:-3},npcLinkDelta:-4,outcome:'npc-prelude-read'}]};
}
export function narratorFor(a,b) {return PAIRS[[a,b].sort().join(':')]?.narrator;}
